import { describe, expect, it } from 'vitest'

import type { AgentTraceDto } from '../../services/apiClient'
import { buildSafetyChecks } from './safetyRules'

const base: AgentTraceDto = { stepNumber: 1, agent: 'SafetyValidation', status: 'Completed', toolsRequested: [], toolsAllowed: [], toolsDenied: [], confidence: 0.9, latencyMilliseconds: 10, outputSchemaValid: true }

describe('buildSafetyChecks', () => {
  it('passes every check for a clean pipeline', () => {
    expect(buildSafetyChecks([base]).every((check) => check.passed)).toBe(true)
  })

  it('fails when a tool was denied, schema invalid or confidence below threshold', () => {
    const checks = buildSafetyChecks([base, { ...base, agent: 'Context', toolsDenied: ['read_lab_reports'], outputSchemaValid: false, confidence: 0.59 }])
    expect(checks.filter((check) => !check.passed)).toHaveLength(3)
  })

  it('fails closed on an empty trace list', () => {
    expect(buildSafetyChecks([]).some((check) => check.passed)).toBe(false)
  })
})
